script:
test("on time submission keeps the raw score", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50.0, rawScore: 45, deadline: 1704067200000, submittedAt: 1704067200000 }), { periodsLate: 0, deduction: 0, score: 45 });
});

test("early submission is not penalised", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1703980800000, submittedAt: 1703980799999 }), { periodsLate: 0, deduction: 0, score: 45 });
});

test("one hour late is one period and loses ten percent of the maximum", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1703980800000, submittedAt: 1703984400000 }), { periodsLate: 1, deduction: 5, score: 40 });
});

test("one millisecond late starts one period", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 30, rawScore: 20, deadline: 1706745600000, submittedAt: 1706745600001 }), { periodsLate: 1, deduction: 3, score: 17 });
});

test("just under half a period still counts as one period", function () {
  assert.equal(code.countLatePeriods({ deadline: 1706659200000, submittedAt: 1706702399999 }), 1);
});

test("exactly half a period counts as one period", function () {
  assert.equal(code.countLatePeriods({ deadline: 1706659200000, submittedAt: 1706702400000 }), 1);
});

test("exactly twenty four hours late is one period", function () {
  assert.equal(code.countLatePeriods({ deadline: 1709078400000, submittedAt: 1709164800000 }), 1);
});

test("one millisecond past twenty four hours is two periods", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1709078400000, submittedAt: 1709164800001 }), { periodsLate: 2, deduction: 10, score: 35 });
});

test("one millisecond before twenty four hours is one period", function () {
  assert.equal(code.countLatePeriods({ deadline: 1709078400000, submittedAt: 1709164799999 }), 1);
});

test("forty nine hours late is three periods", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1706659200000, submittedAt: 1706835600000 }), { periodsLate: 3, deduction: 15, score: 30 });
});

test("exactly ninety six hours late is four periods", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1704067200000, submittedAt: 1704412800000 }), { periodsLate: 4, deduction: 20, score: 25 });
});

test("exactly one hundred twenty hours late is five periods", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1704067200000, submittedAt: 1704499200000 }), { periodsLate: 5, deduction: 25, score: 20 });
});

test("one millisecond past one hundred twenty hours scores zero", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1704067200000, submittedAt: 1704499200001 }), { periodsLate: 6, deduction: 45, score: 0 });
});

test("one hundred twenty hours and one minute late scores zero", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1704067200000, submittedAt: 1704499260000 }), { periodsLate: 6, deduction: 45, score: 0 });
});

test("a penalty larger than the raw score floors at zero", function () {
  assert.deepEqual(code.applyLatePenalty({ maxPoints: 50, rawScore: 10, deadline: 1704067200000, submittedAt: 1704326400000 }), { periodsLate: 3, deduction: 10, score: 0 });
});

test("an unknown field is rejected", function () {
  assert.throws(function () {
    code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1704067200000, submittedAt: 1704067200000, note: 1 });
  }, /unknown field: note/);
});
